/**
 * Bulk issue imports: the persisted import keys and the single transaction
 * that writes a whole batch (labels, issues, label links and the key) at once.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, toIssue } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

/** Default colour of a label created implicitly by an import. */
const IMPORTED_LABEL_COLOR = "#94a3b8";

export interface IssueImportRecord {
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly issueIds: readonly IssueId[];
}

/** One row, already resolved against the workspace (assignee, label names). */
export interface ImportedIssueDraft {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
}

export type ImportWriteResult =
  | { readonly replayed: false; readonly issues: readonly Issue[] }
  | { readonly replayed: true; readonly record: IssueImportRecord };

type Tx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];

function readImport(
  db: Tx | ReturnType<typeof getDb>,
  orgId: OrgId,
  importKey: string,
): IssueImportRecord | null {
  const row = db
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    projectId: brandId<ProjectId>(row.projectId),
    importKey: row.importKey,
    issueIds: (JSON.parse(row.issueIds) as string[]).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  return readImport(getDb(), orgId, importKey);
}

/**
 * Writes the batch in one transaction: nothing is visible unless every row,
 * label and the import key made it. If the key was recorded meanwhile, nothing
 * is written and the existing record is returned instead.
 */
export async function insertImportedIssues(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  rows: readonly ImportedIssueDraft[];
}): Promise<ImportWriteResult> {
  const { orgId, projectId, authorId } = input;

  return getDb().transaction((tx): ImportWriteResult => {
    const existing = readImport(tx, orgId, input.importKey);
    if (existing) return { replayed: true, record: existing };

    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map<string, LabelId>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, orgId))
        .all()
        .map((row) => [row.name, brandId<LabelId>(row.id)]),
    );

    for (const row of input.rows) {
      for (const name of row.labelNames) {
        if (labelIdByName.has(name)) continue;
        const id = newId();
        tx.insert(labels)
          .values({
            id,
            orgId,
            name,
            color: IMPORTED_LABEL_COLOR,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, brandId<LabelId>(id));
      }
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)))
      .get();
    let number = maxRow?.value ?? 0;

    const created: Issue[] = [];
    for (const draft of input.rows) {
      number += 1;
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = [...new Set(draft.labelNames)].map(
        (name) => labelIdByName.get(name) as LabelId,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(labelIds.map((labelId) => ({ orgId, issueId: row.id, labelId })))
          .run();
      }

      created.push(toIssue(row, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        projectId,
        importKey: input.importKey,
        importedBy: authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, issues: created };
  });
}
